INSERT INTO public.chapter_quizzes VALUES (4, 2, 'free_recall', 'Without looking at the lesson, write down everything you remember from the Summary section. What were the What, Why, and How points?', 'The Summary covers 20 life cheat codes across money, career, and life. On money: invest $5K/year in an S&P 500 index fund and never sell — staying in through crashes is the hard part. The FBI framework (Emergency → Essentials → Equity → Enjoyment) structures your spending. On career: chase equity over salary, get a mentor before 40, and move where the action is. On life: only 4% of people can monetize their passion, so build mastery first. The monk''s happiness equation H = O/D sums it all up — manage your desires, not just your possessions.', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.104073', 1, 'Summary', 'The What/Why/How structure compresses 20 cheat codes into a retrievable framework across money, career, and life', '{"key_points": ["20 cheat codes across three domains: money, career, and life", "Invest $5K/year in an S&P 500 index fund and never sell — panic-selling in 2008 permanently cost 40% of net worth", "Only 4% of students can monetize their passion — build mastery first, passion follows", "FBI framework: fund Emergency → Essentials → Equity → Enjoyment in order", "H = O/D: happiness = what you own divided by what you desire — manage desires, not just possessions"]}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (5, 2, 'teach_back', 'Explain the FBI framework as if teaching it to a friend who has never heard of it. Use plain language and an example if it helps.', 'The FBI framework is a simple way to take control of your money. FBI stands for Financial Bureau of Investigation — it forces you to investigate where your money is actually going. You split your cash into four buckets in order: Emergency first (your safety net, 3–6 months of expenses), then Essentials (rent, food, bills), then Equity (savings and investments that build long-term wealth), and finally Enjoyment (holidays, hobbies, entertainment). The rule is strict: you only fill bucket four after the first three are covered. Think of it like a dependency chain — the next step only runs after the previous one completes. It prevents the common trap of spending on luxuries while the emergency fund is still empty.', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.111061', 1, 'Summary', 'The FBI framework makes financial discipline structural — Enjoyment is funded last, not first', '{"key_elements": ["FBI stands for Financial Bureau of Investigation — a personal spending tracking system", "Cash is categorised into four buckets: Emergency, Essentials, Equity, Enjoyment", "Buckets must be funded in order — you only spend on Enjoyment after the first three are covered", "The framework prevents lifestyle inflation by making priority discipline structural"]}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (6, 2, 'cloze', 'Build your ___ to take control of spending: track where your money goes and fund buckets in order — Emergency → Essentials → Equity → Enjoyment.', 'FBI (Financial Bureau of Investigation)', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.113989', 1, 'Summary', 'The FBI framework imposes spending discipline by making Enjoyment the last bucket to fund, not the first', '{"blanks": ["FBI (Financial Bureau of Investigation)"], "context_hint": ""}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (7, 2, 'cloze', 'The monk''s happiness equation is ___: happiness increases when you own more than you desire, and approaches infinity when desires approach zero.', 'H = O/D', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.115783', 1, 'Summary', 'H = O/D reframes happiness as a ratio — managing desire is more powerful than accumulating more', '{"blanks": ["H = O/D"], "context_hint": ""}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (8, 2, 'multiple_choice', 'According to the Summary, what are the two rules for investing in an index fund?', NULL, 'Diversify across asset classes and rebalance annually', 'Put it in an index fund and stay in the market — touch nothing', 'Invest only in bull markets and withdraw before corrections', 'Dollar-cost average weekly and switch to bonds at retirement', '["B"]', '2026-04-01 17:21:17.116972', 1, 'Summary', 'Two rules only: put it in an index fund, and stay in the market no matter what', '{"quiz_learnt": "The two non-negotiable rules for index fund investing", "quiz_type_cognitive": "recall", "response_to_user_option_a": "Incorrect. The lesson does not recommend complex rebalancing strategies — it advocates for simplicity: one rule about putting money in, one rule about keeping it there.", "response_to_user_option_b": "Correct. The lesson states exactly two rules: (1) put it in an index fund and (2) stay in the market — the second being the harder part, especially during crashes.", "response_to_user_option_c": "Incorrect. The lesson explicitly warns against timing the market — the speaker''s own experience of panic-selling in 2008 permanently cost 40% of net worth.", "response_to_user_option_d": "Incorrect. The lesson does not prescribe frequency of contributions or asset switching strategy. The message is radical simplicity: in and stay in."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (41, 6, 'cloze', 'After a project failed publicly at work, Wei applied the failure = teacher principle by writing a ___ — documenting what went wrong and how to fix it — then sent the updated report to the client unprompted.', 'post-mortem', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.277357', 5, 'Story', 'A post-mortem converts failure into structured learning and demonstrates accountability — the client returning confirms that transparency builds more trust than hiding mistakes', '{"blanks": ["post-mortem"], "context_hint": ""}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (43, 6, 'multiple_choice', 'In the Story, what triggered Wei to build his FBI framework across four buckets?', NULL, 'Wei read a finance book that recommended the framework', 'Wei received a pay raise and needed a system to allocate the extra money', 'A colleague was rushed to hospital with a brain tumor — no warning, no financial safety net', 'Wei''s patent was rejected, forcing him to reassess his financial planning', '["C"]', '2026-04-01 17:21:17.279262', 5, 'Story', 'Unexpected catastrophe — not financial planning books — is what makes the emergency fund feel real. The colleague''s brain tumor made the FBI framework urgent, not theoretical', '{"quiz_learnt": "The event that made the emergency fund and FBI framework feel urgent and real", "quiz_type_cognitive": "recall", "response_to_user_option_a": "Incorrect. The story does not mention Wei reading a finance book as the trigger — the prompt was a real, unexpected event in his immediate environment.", "response_to_user_option_b": "Incorrect. The FBI framework was triggered by fear of unexpected catastrophe, not by new income. The pay raise is not mentioned in this part of the story.", "response_to_user_option_c": "Correct. Wei''s colleague suffered a sudden brain tumor with no warning. The shock of ''expect the unexpected'' made Wei examine his own emergency fund and then build the full FBI framework to structure his buckets.", "response_to_user_option_d": "Incorrect. The story mentions Wei''s patent as part of his background anxiety, but a rejection is not described as the trigger for building the FBI framework."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (9, 2, 'multiple_choice', 'The Summary states that only 4% of students can monetize their passion. Which of the following statements correctly explain WHY the lesson advises against following your passion?', NULL, 'Passion-driven careers tend to be in creative fields where monetisation is difficult for most people', 'Passion precedes mastery — you must feel passionate before building skill', 'Following passion is a myth with no supporting research', '96% of people cannot turn their passion into a sustainable income', '["A", "D"]', '2026-04-01 17:21:17.118411', 1, 'Summary', 'Build passion through mastery in something monetizable — don''t wait to ''find'' a passion that also pays', '{"quiz_learnt": "Why passion-following is a flawed career strategy and what to do instead", "quiz_type_cognitive": "understanding", "response_to_user_option_a": "Correct. The lesson notes that people tend to be passionate about creative things like art, music, and photography — domains where monetisation is difficult for most.", "response_to_user_option_b": "Incorrect. The lesson says passion follows mastery, not precedes it. You become great at something, and passion emerges — not the other way around.", "response_to_user_option_c": "Incorrect. The lesson cites a real Canadian university study — this advice is data-backed, not a dismissal of passion itself.", "response_to_user_option_d": "Correct. The Canadian university study found only 4% could monetize their passion, meaning 96% cannot — this is the statistical foundation of the advice."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (11, 2, 'multiple_choice', 'The Summary says to get a mentor ''before 40, not after.'' Which of the following statements correctly explain WHY timing matters for mentorship?', NULL, 'A mentor found at 40 is typically less experienced than one found in your 30s', 'Without a mentor, career navigation is like walking a minefield blindfolded', 'The speaker waited until 40 and then became CEO only 10 years later — earlier mentorship would have compounded sooner', 'Mentors invest more in younger mentees because the long-term ROI for them is higher', '["B", "C"]', '2026-04-01 17:21:17.1255', 1, 'Summary', 'Mentorship compounds over time — waiting until 40 loses decades of directed career acceleration', '{"quiz_learnt": "Why early mentorship compounds career returns that late mentorship cannot fully recover", "quiz_type_cognitive": "understanding", "response_to_user_option_a": "Incorrect. The lesson makes no claim about the experience level of mentors found at different ages — the issue is when you get one, not who they are.", "response_to_user_option_b": "Correct. The speaker explicitly describes navigating his career without a mentor as walking a minefield blindfolded — you lack direction, context, and the benefit of others'' hard lessons.", "response_to_user_option_c": "Correct. The timeline is explicit: got mentors, became CEO 10 years later. Starting at 25 instead of 40 would have put compounding to work 15 years earlier.", "response_to_user_option_d": "Incorrect. The lesson does not discuss what motivates mentors to invest — it focuses entirely on the benefit to the mentee of starting earlier."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (14, 3, 'teach_back', 'Explain the concept of ''status debt'' as shown in the Recommendation flowchart. What is it and why does the flowchart list it as something to kill?', 'Status debt is when you buy expensive things — designer clothes, luxury goods, status symbols — on credit cards in order to signal wealth to others. The problem is that credit cards charge 22–28% annual interest in the US. Every designer purchase you put on a card and don''t pay off immediately costs far more than the sticker price, while the item depreciates. The lesson''s definition of wealth is simple: wealth is what you keep. Status debt destroys the ''keep'' because you''re paying compound interest on things that don''t grow in value. It looks like wealth from the outside but is negative net worth on the inside. It''s like deploying a feature that looks impressive in demos but quietly burns 28% of your compute budget every month.', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.155157', 2, 'Recommendation', 'Status debt is the gap between appearing wealthy and being wealthy — high-interest credit makes it a compounding trap', '{"key_elements": ["Status debt = spending on designer goods and status symbols using high-interest credit", "US average credit card interest is 22–28%, so borrowed status purchases compound against you", "Wealth is defined as what you keep, not what you display — status debt destroys the ''keep'' side", "It is a trap because the debt is invisible while the status symbol is visible"]}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (16, 3, 'cloze', 'The Career Track instructs: negotiate for ___ in your next role — nine out of ten bets miss, but one hit changes your life.', 'equity', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.156998', 2, 'Recommendation', 'Equity has asymmetric upside — nine misses are worth enduring for the one rainmaking event', '{"blanks": ["equity"], "context_hint": ""}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (18, 3, 'multiple_choice', 'The Career Track in the Recommendation flowchart says: ''Move where the action is. Remote won''t grow your network or reputation.'' Which of the following correctly explain WHY the flowchart gives this advice?', NULL, 'Remote work produces lower quality output because people are distracted at home', 'Career = portfolio means connections are assets — remote work limits the rate at which you can acquire them', 'Being physically present creates exposure through collaboration, conflict resolution, and visibility', 'The flowchart believes remote work will be eliminated by companies in the near future', '["B", "C"]', '2026-04-01 17:21:17.158673', 2, 'Recommendation', 'Physical presence compounds network and reputation — two of the most valuable assets in the Career = Portfolio framework', '{"quiz_learnt": "Why physical presence in the right location compounds career growth in ways remote work cannot", "quiz_type_cognitive": "understanding", "response_to_user_option_a": "Incorrect. The lesson does not argue remote workers produce worse output — it argues they miss out on compounding network and reputation effects.", "response_to_user_option_b": "Correct. The Career = Portfolio principle means connections compound like assets. Remote work drastically limits the density and depth of connections you can build.", "response_to_user_option_c": "Correct. The flowchart notes that in-office collaboration, problem-solving, and conflict resolution face-to-face teach skills and build visibility that remote work cannot replicate.", "response_to_user_option_d": "Incorrect. The lesson acknowledges certain roles (software engineering, legal, field sales) can work remotely — but even in those roles, presence accelerates ambitious career growth."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (42, 6, 'cloze', 'Wei stopped thinking ''stable salary'' and started asking: ''Is there any ___ here? Could I own a piece of this?'' — even a 0.2% share changed how he approached his work, making him act like an owner rather than a contractor.', 'equity', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.27834', 5, 'Story', 'Asking about equity is not just a financial question — it triggers the ownership mindset shift that changes how you approach every task', '{"blanks": ["equity"], "context_hint": ""}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (10, 2, 'multiple_choice', 'You are a 35-year-old R&D engineer in Hong Kong. Your monthly salary arrives and half goes to living expenses. Of the remaining half, you currently put everything into a savings account. Applying the FBI framework from the Summary, what should your FIRST priority be for the remaining half?', NULL, 'Invest it all immediately in blue-chip stocks for long-term growth', 'Ensure your Emergency fund covers 3–6 months of expenses before anything else', 'Split evenly across Emergency, Essentials, Equity, and Enjoyment each month', 'Pay off any outstanding credit card balances, then start the FBI order', '["B"]', '2026-04-01 17:21:17.123608', 1, 'Summary', 'Emergency is always bucket one — until it is funded, nothing else in the FBI order can proceed', '{"quiz_learnt": "How to apply the FBI framework ordering to a real salary split scenario", "quiz_type_cognitive": "application", "response_to_user_option_a": "Incorrect. Equity (investments) is the third bucket in the FBI order — you cannot prioritise it before Emergency is fully funded.", "response_to_user_option_b": "Correct. Emergency is the first bucket and must be fully funded before anything else. The lesson is explicit: do not touch it unless there is an emergency.", "response_to_user_option_c": "Incorrect. The FBI framework is sequential, not proportional — you fund each bucket in order, not split evenly across all four simultaneously.", "response_to_user_option_d": "Incorrect. The lesson mentions avoiding credit card debt, but the FBI framework''s prescribed first step is building the Emergency fund — that is the non-negotiable foundation."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (12, 2, 'multiple_choice', 'The Summary says: ''Apply H = O/D daily: manage desires, not just possessions — contentment is a skill, not a circumstance.'' What does the phrase ''contentment is a skill, not a circumstance'' imply about the happiness equation?', NULL, 'You can only be truly happy once your external circumstances are stable', 'Managing desires requires deliberate, repeated practice — it does not happen automatically', 'The equation proves that wealthy people are less happy because their desires always exceed possessions', 'Contentment depends on comparing your situation to those who have less', '["B"]', '2026-04-01 17:21:17.126814', 1, 'Summary', 'H = O/D is actionable because D (desire) is the variable you control — contentment is a daily practice, not a destination', '{"quiz_learnt": "The deeper implication of H = O/D — that happiness is an active practice, not a passive outcome", "quiz_type_cognitive": "analysis", "response_to_user_option_a": "Incorrect. This is exactly what the equation argues against — happiness is not determined by external circumstances but by the ratio of O to D. Waiting for circumstances to improve is the trap the equation dismantles.", "response_to_user_option_b": "Correct. Calling it a ''skill'' means it must be practiced actively — you must notice and reduce desires deliberately, not hope they diminish on their own. The equation gives you the lever (D), but you have to pull it.", "response_to_user_option_c": "Incorrect. The lesson does not claim wealthy people are less happy — it argues anyone at any wealth level can manipulate D to improve happiness regardless of O.", "response_to_user_option_d": "Incorrect. The equation is entirely internal — O ÷ D refers to your own desires versus your own possessions, not a comparison to anyone else."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (13, 3, 'free_recall', 'Without looking at the lesson, recall the three tracks in the Recommendation flowchart. What are the key action steps in each track?', 'The Recommendation flowchart has three parallel tracks. The Money Track covers: open an index fund and never sell, build an emergency fund (3–6 months), apply the FBI order (Emergency → Essentials → Equity → Enjoyment), automate all finances, and avoid status debt (no designer items on 22–28% credit). The Career Track covers: move where the action is, find a mentor now (not at 40), negotiate for equity (9/10 miss but one hit changes your life), and log 15,000 hours over 5 years. The Mindset Track covers: do a 1-week social media detox, reframe every failure as a teacher, ask for help despite fear of rejection, and drop grudges (business is never personal). All three tracks end at H = O/D.', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.152973', 2, 'Recommendation', 'The three-track flowchart makes the 20 cheat codes actionable — Money, Career, and Mindset each have concrete first steps you can take this week', '{"key_points": ["Money Track: index fund (auto-deposit, never sell), emergency fund (3–6 months), FBI order, automate all finances, kill status debt", "Career Track: move where the action is, find a mentor now, negotiate for equity, log 15,000 hours over 5 years", "Mindset Track: 1-week social media detox, reframe failures as lessons, ask for help, drop grudges", "All three tracks converge at H = O/D as the closing principle"]}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (15, 3, 'cloze', 'The Money Track closes with this rule: kill ___ — avoid designer purchases on high-interest credit. Wealth is what you keep, not what you display.', 'status debt', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.156228', 2, 'Recommendation', 'Status debt silently destroys wealth by adding compound interest to depreciating purchases', '{"blanks": ["status debt"], "context_hint": ""}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (17, 3, 'multiple_choice', 'In the Recommendation flowchart, which track comes AFTER the Money and Career tracks converge?', NULL, 'Investment Track', 'Mindset Track', 'Legacy Track', 'Skills Track', '["B"]', '2026-04-01 17:21:17.157865', 2, 'Recommendation', 'The Recommendation flowchart has three sequential tracks: Money → Career → Mindset, all converging at H = O/D', '{"quiz_learnt": "The three-track structure and sequence of the Recommendation flowchart", "quiz_type_cognitive": "recall", "response_to_user_option_a": "Incorrect. There is no ''Investment Track'' in the flowchart — investing is one step within the Money Track.", "response_to_user_option_b": "Correct. After the Money and Career tracks converge, they flow into the Mindset Track, which covers social media detox, reframing failure, asking for help, and dropping grudges.", "response_to_user_option_c": "Incorrect. There is no ''Legacy Track'' in the flowchart — legacy themes appear in the Visual Chunk''s LIFE quadrant.", "response_to_user_option_d": "Incorrect. Skills appear in the Career Track (15,000 hours) but there is no separate ''Skills Track''."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (19, 3, 'multiple_choice', 'You receive a pay raise at your Hong Kong startup. Applying the Money Track from the Recommendation flowchart, which of the following is the correct first action with the extra income?', NULL, 'Invest it immediately in an index fund to maximise compound growth', 'Check whether your Emergency fund already covers 3–6 months of expenses; top it up if not', 'Split the raise evenly: index fund, emergency fund, and a treat for yourself', 'Use it to negotiate equity — offer to take a lower raise in exchange for a higher stake', '["B"]', '2026-04-01 17:21:17.159473', 2, 'Recommendation', 'Extra income follows the FBI order — Emergency first, then Essentials, then Equity, then Enjoyment', '{"quiz_learnt": "How to apply the FBI order when new income arrives", "quiz_type_cognitive": "application", "response_to_user_option_a": "Incorrect. Equity (investing) is the third bucket in the FBI order. If your Emergency fund is not fully funded, investing extra income skips the required first step.", "response_to_user_option_b": "Correct. The Money Track follows the FBI order — Emergency first. Extra income should fill the Emergency bucket to 3–6 months before anything else is funded.", "response_to_user_option_c": "Incorrect. The FBI framework is sequential, not proportional. Treating yourself (Enjoyment) before Emergency and Equity are covered violates the order.", "response_to_user_option_d": "Incorrect. Negotiating equity is a Career Track action, not a Money Track action. It does not override the FBI priority order for allocating new income."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (21, 3, 'multiple_choice', 'A software engineer follows the Money Track perfectly but ignores the Career Track entirely — no mentor, no equity, never moved where the action is. By the end of the Recommendation flowchart, what is the most likely outcome?', NULL, 'Financial security but limited career ceiling — wealth grows slowly through index funds but no rainmaking event occurs', 'No outcome at all — the flowchart only works if all three tracks are followed simultaneously', 'The same outcome as following all three tracks, since the Money Track is the most important', 'Career failure — ignoring the Career Track means no income to fund the Money Track', '["A"]', '2026-04-01 17:21:17.161198', 2, 'Recommendation', 'Each track compounds independently — the Money Track builds a floor, but the Career Track is needed for the ceiling-breaking rainmaking event', '{"quiz_learnt": "Why all three tracks are necessary and what is lost by ignoring any one of them", "quiz_type_cognitive": "analysis", "response_to_user_option_a": "Correct. Index fund investing will grow wealth slowly over decades, but without equity, mentorship, or relocation, the ceiling is a salary. The rainmaking event — the one equity hit that changes your life — never happens. Financial security without career acceleration.", "response_to_user_option_b": "Incorrect. The three tracks are independent action paths — following one still produces its specific outcomes. Missing the Career Track does not nullify the Money Track.", "response_to_user_option_c": "Incorrect. The lesson treats Career and Money as separate compounding engines. Missing the Career Track means missing equity upside and mentorship acceleration — these are not replaceable by the Money Track.", "response_to_user_option_d": "Incorrect. The engineer still has a salary (income), so the Money Track remains fundable. The cost is opportunity — not survival."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (22, 4, 'free_recall', 'Without looking at the lesson, write down as many of the five one-liners from the One-Liners section as you can. Try to recall their exact wording.', 'The five one-liners are: (1) "Saving is not investing." (2) "Salary buys you furniture. Equity buys your future." (3) "Failure is not your tormentor — it''s your teacher." (4) "Wealth isn''t about what you buy. It''s about what you keep." (5) "When your desires approach zero, your happiness goes to infinity."', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.188568', 3, 'One-Liners', 'These five phrases are compressed memory handles — if you can recall and explain each one, you have internalised the lesson''s core frameworks', '{"key_points": ["\"Saving is not investing.\"", "\"Salary buys you furniture. Equity buys your future.\"", "\"Failure is not your tormentor — it''s your teacher.\"", "\"Wealth isn''t about what you buy. It''s about what you keep.\"", "\"When your desires approach zero, your happiness goes to infinity.\""]}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (24, 4, 'cloze', 'Failure is not your ___ — it''s your teacher.', 'tormentor', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.193207', 3, 'One-Liners', 'Reframing failure as a teacher rather than a tormentor transforms setbacks into preparation for future success', '{"blanks": ["tormentor"], "context_hint": ""}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (26, 4, 'multiple_choice', 'Which of the five one-liners in the lesson directly addresses investment strategy?', NULL, '"Failure is not your tormentor — it''s your teacher."', '"Wealth isn''t about what you buy. It''s about what you keep."', '"Saving is not investing."', '"When your desires approach zero, your happiness goes to infinity."', '["C"]', '2026-04-01 17:21:17.195703', 3, 'One-Liners', '"Saving is not investing" targets the most common financial misconception — a savings account and an index fund are not the same thing', '{"quiz_learnt": "Matching each one-liner to the domain it compresses", "quiz_type_cognitive": "recall", "response_to_user_option_a": "Incorrect. This one-liner addresses the Mindset domain — specifically how to reframe failure — not investment strategy.", "response_to_user_option_b": "Incorrect. This one-liner addresses wealth accumulation and spending habits (avoid status debt), not the specific difference between saving and investing.", "response_to_user_option_c": "Correct. This one-liner directly targets a common misconception about money — that putting money in a savings account is equivalent to investing. The lesson argues they are fundamentally different in terms of compounding effect.", "response_to_user_option_d": "Incorrect. This one-liner addresses the H = O/D happiness equation and desire management — not investment."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (28, 4, 'multiple_choice', 'You are presenting an AI model demo to a client. The model misfires on a key test case and the meeting ends early. Your first instinct is to avoid the team for a week. Which one-liner from the One-Liners section most directly challenges that instinct?', NULL, '"Saving is not investing."', '"Salary buys you furniture. Equity buys your future."', '"Failure is not your tormentor — it''s your teacher."', '"When your desires approach zero, your happiness goes to infinity."', '["C"]', '2026-04-01 17:21:17.197705', 3, 'One-Liners', 'When failure tempts you to hide, the ''failure = teacher'' reframe redirects energy toward the post-mortem and the fix — not avoidance', '{"quiz_learnt": "Applying the failure reframe to a real professional setback", "quiz_type_cognitive": "application", "response_to_user_option_a": "Incorrect. This one-liner is about investment strategy — it does not apply to a professional failure scenario.", "response_to_user_option_b": "Incorrect. This one-liner is about career compensation strategy — it does not address how to respond to a failed demo.", "response_to_user_option_c": "Correct. Avoiding the team after a failure is treating failure as a tormentor — something to hide from. The one-liner reframes failure as a teacher: the right response is to extract the lesson, fix the model, and re-engage.", "response_to_user_option_d": "Incorrect. This one-liner is about desire management and the H = O/D happiness equation — not about professional failure responses."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (20, 3, 'multiple_choice', 'The Money Track in the Recommendation flowchart recommends automating all finances: savings before paycheck, auto bills, and auto spending limits. Which of the following correctly explain WHY automation is recommended?', NULL, 'Automation removes the need to ever think about money again', 'Saving and investing before the paycheck hits means you never face the temptation to spend first', 'Automation reduces the risk of missing payments due to forgetfulness, which protects credit scores', 'Automated systems earn higher interest rates than manual deposits', '["B", "C"]', '2026-04-01 17:21:17.160278', 2, 'Recommendation', 'Automation removes willpower from the equation — savings happen before temptation arises and bills are never missed', '{"quiz_learnt": "Why automating finances is more effective than relying on willpower and discipline", "quiz_type_cognitive": "understanding", "response_to_user_option_a": "Incorrect. Automation reduces decision fatigue but does not eliminate the need for financial awareness — you still need to monitor your FBI buckets and adjust over time.", "response_to_user_option_b": "Correct. The flowchart specifies ''savings before paycheck'' — by automating transfers the moment income arrives, you remove the willpower requirement and never have the chance to spend what is already allocated.", "response_to_user_option_c": "Correct. Auto-paying bills eliminates the risk of late fees and credit score damage from forgetfulness — a structural protection, not a discipline requirement.", "response_to_user_option_d": "Incorrect. The lesson makes no claim about automation earning higher interest — the benefit is behavioural, not financial."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (23, 4, 'teach_back', 'Explain the one-liner ''Salary buys you furniture. Equity buys your future.'' as if teaching it to a junior colleague who just received their first job offer.', 'The one-liner draws a contrast between two types of financial reward. Salary is transactional: you trade hours for money, you spend the money, and the cycle resets. It lets you buy what you need right now — furniture, living expenses, comfort. But equity — owning a share of something — compounds. If the company grows, your stake grows without additional hours worked. Equity also changes how you think: once you own a piece of something, even a small percentage, you stop being a contractor and start thinking like a builder. Nine out of ten equity bets might be worth nothing, but one ''rainmaking event'' — one company that actually takes off — can change your financial life in a way that no salary ever could. The line isn''t saying salary is bad; it''s saying salary has a ceiling and equity doesn''t.', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.189929', 3, 'One-Liners', 'Salary has a ceiling but equity has asymmetric upside — and owning equity changes how you think about your work, regardless of whether it pays off', '{"key_elements": ["Salary is linear — you work, get paid, spend, and the cycle resets with no compounding", "Equity is exponential — your stake can grow independently of additional hours worked", "Equity creates an ownership mindset shift: you think like a builder, not a contractor", "9 out of 10 equity bets miss, but one rainmaking event can change your financial life permanently"]}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (25, 4, 'cloze', '___ buys you furniture. Equity buys your future.', 'Salary', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.194753', 3, 'One-Liners', 'Salary provides present comfort; equity provides future upside — the distinction drives the ownership mindset shift', '{"blanks": ["Salary"], "context_hint": ""}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (27, 4, 'multiple_choice', 'The one-liners ''Failure is not your tormentor — it''s your teacher'' and ''Wealth isn''t about what you buy. It''s about what you keep.'' share an underlying structural pattern. Which of the following correctly identifies what they have in common?', NULL, 'Both use analogies to physical objects to make abstract concepts tangible', 'Both reframe something typically seen as negative or trivial into something with strategic value', 'Both address money and financial decision-making', 'Both are direct quotes from the transcript with no paraphrasing', '["B"]', '2026-04-01 17:21:17.196795', 3, 'One-Liners', 'Good one-liners work by reframing — they take something familiar and flip the default assumption to reveal the lesson''s core insight', '{"quiz_learnt": "How the one-liners use reframing to shift perspective on familiar concepts", "quiz_type_cognitive": "understanding", "response_to_user_option_a": "Incorrect. Neither one-liner uses a physical object analogy — ''tormentor/teacher'' and ''buy/keep'' are abstract reframes, not physical metaphors.", "response_to_user_option_b": "Correct. Failure is typically feared and avoided — the one-liner reframes it as a teacher with strategic value. Buying is typically associated with wealth — the one-liner reframes it so that keeping (not buying) defines wealth. Both flip the common assumption.", "response_to_user_option_c": "Incorrect. Only the wealth one-liner addresses money. The failure one-liner is in the Mindset domain.", "response_to_user_option_d": "Incorrect. One-liners are compressed distillations designed for memorability — they may paraphrase or sharpen ideas from the transcript."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (29, 4, 'multiple_choice', 'The one-liner ''When your desires approach zero, your happiness goes to infinity'' uses mathematical language. Which of the following correctly explain what this phrasing implies?', NULL, 'True happiness is only achievable by becoming a monk who owns nothing', 'The relationship between desire and happiness is a mathematical limit — as one denominator approaches zero, the ratio grows unboundedly', 'Reducing desires even slightly produces a disproportionately large improvement in happiness', 'Complete elimination of desire is the required goal for this principle to have any practical effect', '["B", "C"]', '2026-04-01 17:21:17.19923', 3, 'One-Liners', 'The one-liner expresses H = O/D as a mathematical limit — even small reductions in desire have disproportionate effects on happiness because D is the denominator', '{"quiz_learnt": "The mathematical logic of H = O/D expressed as a limit", "quiz_type_cognitive": "understanding", "response_to_user_option_a": "Incorrect. The lesson does not prescribe becoming a monk — it uses monk wisdom to illustrate a ratio that anyone can apply. The goal is to manage desires, not eliminate all possessions.", "response_to_user_option_b": "Correct. In H = O/D, D is the denominator. As D approaches zero, O/D approaches infinity — this is the mathematical limit the one-liner expresses. Even a small reduction in D moves the ratio significantly.", "response_to_user_option_c": "Correct. Because D is in the denominator, small reductions produce large effects — especially when D is already small. This is the disproportionate leverage the one-liner captures.", "response_to_user_option_d": "Incorrect. The lesson says desires approaching zero produces happiness approaching infinity — not that zero desire is required or even achievable. The principle is about direction, not perfection."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (30, 4, 'multiple_choice', 'A colleague earns 50% more than you but spends all of it on designer goods, premium subscriptions, and lifestyle upgrades — he has no savings and carries credit card debt. Which one-liner most directly explains why he is likely less wealthy than you despite the higher income?', NULL, '"Saving is not investing."', '"Salary buys you furniture. Equity buys your future."', '"Failure is not your tormentor — it''s your teacher."', '"Wealth isn''t about what you buy. It''s about what you keep."', '["D"]', '2026-04-01 17:21:17.20048', 3, 'One-Liners', 'Income minus spending equals wealth — the one-liner ''wealth is what you keep'' explains why high earners who spend everything have less wealth than moderate earners who save consistently', '{"quiz_learnt": "Understanding wealth as retained value, not earned income", "quiz_type_cognitive": "analysis", "response_to_user_option_a": "Incorrect. This one-liner targets the misconception that savings accounts are equivalent to investing — the colleague''s issue is not about savings accounts but about spending all income on consumption.", "response_to_user_option_b": "Incorrect. This one-liner addresses the choice between salary and equity compensation — it does not directly explain why spending all earnings leaves a person with no wealth.", "response_to_user_option_c": "Incorrect. This is a mindset one-liner about reframing failure — it does not apply to a spending and wealth accumulation scenario.", "response_to_user_option_d": "Correct. The colleague earns more but keeps nothing — wealth is defined by what remains after spending, not by income earned. The one-liner directly captures why higher income with higher spending produces less wealth than lower income with disciplined retention."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (31, 5, 'free_recall', 'Without looking at the lesson, recall the Visual Chunk grid. What are the four main quadrants and the LIFE box? Name at least two cheat codes from each area.', 'The Visual Chunk organises the 20 cheat codes into four quadrants and a LIFE box. MONEY: index fund + stay in, emergency fund (3–6 months), FBI (Emergency → Essentials → Equity → Enjoyment), no status debt, financial literacy, automate everything. CAREER: career = portfolio (skills + connections compound), move where the action is, equity > salary, get a mentor (not at 40). MINDSET: build passion don''t follow it (96% can''t monetize passion), no victim card. GROWTH: practice relentlessly, go analog (read books, not doom scroll), failure = teacher (fired 3×, each led somewhere), ask for help. LIFE box: choose partner with System 2 (rational, slow), forgive past, bring value to others, H = O/D.', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.232135', 4, 'Visual Chunk', 'The Visual Chunk maps all 20 cheat codes into five thematic areas — seeing them together reveals which domains are most underdeveloped in your own life', '{"key_points": ["MONEY: index fund + stay in, emergency fund, FBI (4 Es), no status debt, financial literacy, automate everything", "CAREER: career = portfolio, move where action is, equity > salary, get a mentor (not at 40)", "MINDSET: build passion don''t follow, no victim card", "GROWTH: practice relentlessly, go analog (read books), failure = teacher, ask for help", "LIFE (bottom box): choose partner with System 2, forgive past, bring value, H = O/D"]}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (33, 5, 'cloze', 'The MINDSET quadrant warns against ___, which kills critical thinking — recommending going analog and reading books instead.', 'doom scrolling', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.236699', 4, 'Visual Chunk', 'Doom scrolling degrades the focused thinking that reading builds — the Visual Chunk flags it as a direct threat to the MINDSET quadrant', '{"blanks": ["doom scrolling"], "context_hint": ""}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (35, 5, 'multiple_choice', 'In the Visual Chunk grid, which quadrant contains ''failure = teacher''?', NULL, 'MONEY', 'CAREER', 'MINDSET', 'GROWTH', '["D"]', '2026-04-01 17:21:17.239304', 4, 'Visual Chunk', 'Failure = teacher belongs in GROWTH because reframing failure is a skill that drives improvement — it compounds alongside practice and asking for help', '{"quiz_learnt": "The thematic organisation of the 20 cheat codes across the Visual Chunk quadrants", "quiz_type_cognitive": "recall", "response_to_user_option_a": "Incorrect. The MONEY quadrant contains financial cheat codes: index fund, emergency fund, FBI, no status debt, financial literacy, automate everything.", "response_to_user_option_b": "Incorrect. The CAREER quadrant contains: career = portfolio, move where action is, equity > salary, get a mentor.", "response_to_user_option_c": "Incorrect. The MINDSET quadrant contains: build passion (don''t follow it), and no victim card.", "response_to_user_option_d": "Correct. The GROWTH quadrant groups the skill-building and resilience codes: practice relentlessly, go analog (read books), failure = teacher, and ask for help."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (37, 5, 'multiple_choice', 'You are a staff R&D engineer at a Hong Kong startup. You review the Visual Chunk and realise you have been strong on MONEY (index fund, FBI) but have never asked for help, avoid giving post-mortems after failures, and spend 3 hours a day scrolling tech news. Which Visual Chunk quadrant most urgently needs attention?', NULL, 'CAREER', 'MONEY', 'GROWTH', 'LIFE', '["C"]', '2026-04-01 17:21:17.243889', 4, 'Visual Chunk', 'The Visual Chunk is a self-audit tool — map your current habits to each quadrant to identify which compounding engine is most neglected', '{"quiz_learnt": "How to use the Visual Chunk as a self-assessment tool to identify gaps", "quiz_type_cognitive": "application", "response_to_user_option_a": "Incorrect. The described behaviours (not asking for help, avoiding post-mortems, doom scrolling) do not map to the CAREER quadrant, which covers portfolio building, relocation, equity, and mentorship.", "response_to_user_option_b": "Incorrect. MONEY is described as already strong — index fund and FBI are in place.", "response_to_user_option_c": "Correct. All three described gaps map directly to the GROWTH quadrant: not asking for help (ask for help), avoiding post-mortems (failure = teacher), and doom scrolling tech news (go analog). GROWTH needs the most urgent attention.", "response_to_user_option_d": "Incorrect. The LIFE quadrant covers partner choice, forgiveness, bringing value, and H = O/D — none of the described behaviours map here."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (40, 6, 'teach_back', 'In the Story, Wei starts ''acting like an owner, not a contractor'' after asking about equity. Explain what this mindset shift means and why the story shows it matters.', 'When Wei asked about equity and received a 0.2% stake, he did not get rich overnight — 0.2% is small. But what changed was how he thought about his work. Before equity, he was a contractor: do the task, get paid, go home. After equity, he became an owner: he started caring whether the company succeeded, whether his models actually solved client problems, and whether his skills were compounding assets or just deliverables. The story shows this shift when Wei asks himself ''Is there any equity here? Could I own a piece of this?'' — the question itself reveals the mindset change. It is like the difference between a developer who codes to close a ticket and one who thinks about the product''s long-term architecture. Same work, fundamentally different engagement and quality of output.', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.275953', 5, 'Story', 'Equity creates an ownership mindset that changes work quality and engagement — even a small stake shifts you from contractor to builder', '{"key_elements": ["Owner mindset = caring about outcomes, not just completing tasks — thinking about the company''s success", "Even a tiny equity stake (0.2%) creates psychological skin in the game", "The shift is internal — it changes how Wei approaches his work, not just what he is paid", "He starts treating each project as a portfolio position, not a ticket to close"]}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (32, 5, 'teach_back', 'The Visual Chunk includes ''Career = Portfolio'' in the CAREER quadrant. Explain this concept as if teaching it to a PhD student about to start their first industry job.', 'Treating your career like an investment portfolio means seeing every skill you build and every person you work with as an asset that compounds over time. Just as a financial portfolio grows when you keep adding to it without withdrawing prematurely, your career portfolio grows when you accumulate skills and connections across roles. The speaker started as a help-desk guy in a dark, windowless room doing 14–15 hour days. But he was not just doing the job — he was compounding. By the time he had 15,000 hours over 5 years, he had built a portfolio so valuable that promotion to program manager followed naturally — and CEO came 20 years later. For a PhD student entering industry, the first years may feel like grunt work. They are the deposit phase. The compound interest comes later — if you invest the hours with deliberate intent.', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.234319', 4, 'Visual Chunk', 'Career = Portfolio means every skill and relationship is an asset — early deposits compound into disproportionate career returns later', '{"key_elements": ["A career portfolio = a collection of skills and connections that compounds over time, like a financial portfolio", "Each project, collaboration, and role is a ''position'' — effort compounds like interest over years", "The speaker went from help-desk to CEO in under 20 years through 15,000 hours of deliberate compounding", "Starting at the bottom is the deposit phase — the compound interest comes later if you invest deliberately"]}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (34, 5, 'cloze', 'The LIFE quadrant advises choosing a partner using ___ thinking — the slow, rational part of the brain that evaluates long-term compatibility — rather than fast emotional gut reaction.', 'System 2', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.238323', 4, 'Visual Chunk', 'System 2 thinking (slow, rational) produces better long-term partner choices than System 1 (fast, emotional) — the most important life decision warrants the most deliberate thinking', '{"blanks": ["System 2"], "context_hint": ""}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (36, 5, 'multiple_choice', 'The Visual Chunk places the LIFE box (System 2 partner choice, forgive past, bring value, H = O/D) at the bottom, separate from the four quadrants. Which of the following best explains WHY the LIFE codes are separated?', NULL, 'The LIFE codes are less important than the Money and Career codes', 'The LIFE codes are harder to action and therefore placed at the end as optional stretch goals', 'The LIFE codes represent foundational decisions that underpin all quadrants — they span the full bottom of the chart to signal broad influence', 'The LIFE codes were added as an afterthought to the original 16 cheat codes', '["C"]', '2026-04-01 17:21:17.240735', 4, 'Visual Chunk', 'The LIFE box at the bottom of the Visual Chunk is the foundation — partner choice and happiness management affect the capacity to execute every other quadrant', '{"quiz_learnt": "The structural logic of separating life-level codes from the operational quadrants", "quiz_type_cognitive": "understanding", "response_to_user_option_a": "Incorrect. The lesson gives the LIFE codes significant weight — choosing the wrong partner is described as ''emotionally bankrupt'' and H = O/D closes the entire lesson. Placement at the bottom signals foundation, not low priority.", "response_to_user_option_b": "Incorrect. The lesson does not describe LIFE codes as optional — the speaker says choosing your partner wisely is the most important decision you will make.", "response_to_user_option_c": "Correct. The LIFE box spans the full width at the bottom — it is the foundation. Partner choice, forgiveness, values, and happiness management underpin how effectively you can execute every other quadrant.", "response_to_user_option_d": "Incorrect. There is no evidence in the lesson that LIFE codes were added later — they include cheat codes 17–20, which are integral to the original framework."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (38, 5, 'multiple_choice', 'Comparing the MONEY and CAREER quadrants in the Visual Chunk, both contain ''compounding'' logic. Which of the following correctly identifies the key difference in HOW compounding works in each?', NULL, 'MONEY compounds passively once invested; CAREER compounds actively through deliberate skill-building and connections', 'MONEY compounds faster because financial markets grow faster than human skills', 'CAREER compounding only works for people who move cities; MONEY compounding works for everyone', 'Both quadrants use identical compounding mechanisms — the only difference is the asset type', '["A"]', '2026-04-01 17:21:17.245133', 4, 'Visual Chunk', 'MONEY compounds passively (deposit and stay in); CAREER compounds actively (deliberate skill-building and network investment over years)', '{"quiz_learnt": "The distinction between financial compounding (MONEY) and skills/network compounding (CAREER)", "quiz_type_cognitive": "analysis", "response_to_user_option_a": "Correct. Index fund compounding is passive — you deposit and leave it. Career compounding (15,000 hours, skills, connections) requires active, deliberate investment of time and effort. The mechanism is analogous but the required action is different.", "response_to_user_option_b": "Incorrect. The lesson does not compare the growth rates of financial markets versus human skill development — both are presented as powerful compounding engines worth pursuing.", "response_to_user_option_c": "Incorrect. The lesson recommends moving where the action is as one Career Track step, but it does not claim career compounding fails without relocation. Remote workers can still build skills and connections, just more slowly.", "response_to_user_option_d": "Incorrect. The mechanisms differ meaningfully: money compounds automatically once invested; career compounds only with active hours, deliberate practice, and relationship building."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (39, 6, 'free_recall', 'Without looking at the lesson, recall the Story section. Who is Wei, what was his situation, and which cheat codes did he apply at each stage?', 'Wei is a 35-year-old R&D engineer at a small Hong Kong startup who splits his salary between living expenses and fragmented savings. Cheat codes 1–2: he opens an index fund with auto-transfer and resists selling during a dip, recalling the story of the man who panic-sold in 2008. Cheat codes 4–6: he stops thinking ''stable salary'' and starts asking about equity — even a 0.2% stake changes his mindset from contractor to owner. Cheat codes 7–9: after a colleague gets a brain tumor with no warning, he builds his FBI spreadsheet and commits to funding bucket four (Enjoyment) only after the first three are covered. Cheat codes 14–16: after a demo fails publicly, he writes a post-mortem, fixes the model, and sends it to the client unprompted — the client returns. Cheat code 20: he writes H = O/D on a Post-it by his monitor and starts subtracting desires — the anxiety hum gets quieter.', NULL, NULL, NULL, NULL, 'null', '2026-04-01 17:21:17.274268', 5, 'Story', 'Wei''s story shows the cheat codes applied within real constraints — salary dependency, family obligations, and an unsold patent — making them concrete and achievable', '{"key_points": ["Wei: 35-year-old R&D engineer in Hong Kong, half salary to expenses, patent unsold", "Cheat codes 1–2: opened index fund, set auto-transfer, resisted selling during a market dip", "Cheat codes 4–6: treated career as portfolio, asked about equity (0.2%), started acting like an owner", "Cheat codes 7–9: built FBI framework across four buckets after a colleague''s brain tumor shock", "Cheat codes 14–16: wrote post-mortem after a failed demo, fixed the model, sent client an update unprompted", "Cheat code 20: put H = O/D on a Post-it, subtracted desires instead of adding income"]}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (44, 6, 'multiple_choice', 'In the Story, Wei watches his index fund numbers fall during a market dip and feels the pull to sell — but doesn''t. The story then references ''the man who panic-sold in 2008 and never went back — permanently 40% poorer.'' Which of the following correctly explain why this moment in Wei''s story is significant?', NULL, 'It shows that market dips are always followed by immediate recoveries, making selling pointless', 'It illustrates that intellectual knowledge of the rule (''stay in'') is insufficient — the real test is behaviour under emotional pressure', 'It demonstrates that Wei is a better investor than the man in 2008 because Wei has read more about investing', 'It confirms that the permanent 40% loss is always the outcome when someone sells during a crash', '["B"]', '2026-04-01 17:21:17.280322', 5, 'Story', 'Knowing rule two (''stay in'') is easy; following it during a falling market is the actual test — Wei''s story shows that emotional override is the real skill', '{"quiz_learnt": "Why the hardest part of the two-rule investing strategy is rule two — staying in", "quiz_type_cognitive": "understanding", "response_to_user_option_a": "Incorrect. The lesson does not claim dips are always followed by immediate recoveries — the 2008 example shows a multi-year recovery that the panic-seller missed by refusing to re-enter.", "response_to_user_option_b": "Correct. Wei knows the rule intellectually. The story''s significance is that he is tested in real-time: the numbers are falling, the pull to sell is real, and he has to actively override his emotion. This is why the lesson says staying in is ''the hard part.''", "response_to_user_option_c": "Incorrect. The story does not attribute Wei''s discipline to superior reading or knowledge — it attributes it to recalling the concrete consequence of panic-selling (40% permanent loss).", "response_to_user_option_d": "Incorrect. The 40% permanent loss was specific to someone who sold AND then refused to re-enter as the market recovered — it is a behavioural outcome, not an automatic consequence of selling."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (46, 6, 'multiple_choice', 'In the Story, Wei writes ''H = O/D'' on a Post-it and sticks it to his monitor. He then ''starts subtracting desires instead of adding income.'' Which of the following correctly explain what this action demonstrates about applying H = O/D?', NULL, 'Wei has decided to stop earning more and live on a reduced income', 'The Post-it serves as a daily prompt — keeping H = O/D visible makes desire management a habit rather than an occasional reflection', 'Subtracting desires means eliminating all spending beyond basic necessities', 'Wei has understood that he cannot increase income, so the only lever available to him is reducing desire', '["B"]', '2026-04-01 17:21:17.282683', 5, 'Story', 'Making H = O/D visible as a daily prompt converts an intellectual insight into a behavioural habit — desire management requires repeated, intentional practice', '{"quiz_learnt": "How H = O/D is practiced as a daily habit, not a one-time insight", "quiz_type_cognitive": "understanding", "response_to_user_option_a": "Incorrect. The story does not say Wei decided to stop earning more — he continues working as an R&D engineer. The action is about managing the denominator (D), not reducing the numerator (O).", "response_to_user_option_b": "Correct. The Post-it is a environmental reminder — by making H = O/D visible at his monitor, Wei builds a habit of questioning each new desire before it enters the denominator. This is contentment as a daily practice, not a one-time insight.", "response_to_user_option_c": "Incorrect. The story does not describe Wei cutting spending to bare necessities — ''subtracting desires'' means questioning and reducing the wants he notices arising, not extreme austerity.", "response_to_user_option_d": "Incorrect. Wei does have the lever of increasing income (career growth, equity), but the H = O/D insight reveals that reducing desire is an immediately available and equally powerful lever — not the only one."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (45, 6, 'multiple_choice', 'In the Story, after Wei''s demo misfired publicly, he spent a week avoiding his team. Applying cheat code 16 (''don''t play the victim card / business is never personal''), what should Wei have done instead?', NULL, 'Accepted the failure silently and waited for the client to forget about it', 'Blamed the colleague who had pointed out the flaw before the demo', 'Written a post-mortem, fixed the model, and re-engaged with both the team and client proactively', 'Requested a new project assignment to avoid future association with the failed demo', '["C"]', '2026-04-01 17:21:17.281664', 5, 'Story', '''Business is never personal'' means the correct response to a professional failure is proactive repair — post-mortem, fix, re-engage — not retreat', '{"quiz_learnt": "Applying the ''no victim card'' principle to a professional failure scenario", "quiz_type_cognitive": "application", "response_to_user_option_a": "Incorrect. Waiting passively is still avoidance — it is not the same as the ''no victim card'' principle, which calls for active re-engagement. The client returning in the story was a result of Wei''s proactive follow-up, not passive waiting.", "response_to_user_option_b": "Incorrect. Blaming a colleague is the opposite of ''business is never personal'' — it escalates the personal dimension and avoids learning from the failure.", "response_to_user_option_c": "Correct. The story shows exactly this: Wei wrote a post-mortem (failure = teacher), fixed the model (ownership), and sent the client an updated report unprompted (no victim card — business is never personal). The client came back.", "response_to_user_option_d": "Incorrect. Requesting reassignment is also avoidance — it is treating the failure as a tormentor (something to escape) rather than a teacher (something to learn from and address)."}') ON CONFLICT DO NOTHING;
INSERT INTO public.chapter_quizzes VALUES (47, 6, 'multiple_choice', 'At the end of the Story, Wei feels ''the hum got quieter'' after applying H = O/D. He had been scrolling tech news late at night and feeling anxious about colleagues raising rounds and an unsold patent. What does ''the hum got quieter'' reveal about the relationship between desire, anxiety, and H = O/D?', NULL, 'The hum got quieter because Wei''s patent was eventually sold, reducing financial anxiety', 'The hum was anxiety caused by a growing D (desire for more recognition, bigger company, sold patent) — reducing D through H = O/D addressed the root cause of the anxiety', 'The hum got quieter because Wei stopped using social media entirely, removing the trigger', 'The hum represents background stress from work, which H = O/D has no direct mechanism to address', '["B"]', '2026-04-01 17:21:17.284201', 5, 'Story', 'The ''hum'' of anxiety is often a symptom of inflated D — comparing what you own to what others have. H = O/D quietens it by targeting desire directly, without requiring external circumstances to change', '{"quiz_learnt": "The connection between unmanaged desires and baseline anxiety — and how H = O/D addresses the root cause", "quiz_type_cognitive": "analysis", "response_to_user_option_a": "Incorrect. The story does not say the patent was sold — the hum quietened before any external circumstance changed, which is the entire point. H = O/D works by changing the denominator, not waiting for the numerator to grow.", "response_to_user_option_b": "Correct. Wei''s anxiety came from comparing his situation (what he owns: current job, salary, unsold patent) to what he desired (others'' funding rounds, bigger companies). H = O/D reveals that his D was inflated by comparison. Subtracting desires reduced D, which increased the ratio — and the anxiety hum, being a symptom of D > O, got quieter.", "response_to_user_option_c": "Incorrect. The story implies Wei reduced scrolling but the mechanism of relief was desire subtraction, not just trigger removal. The H = O/D framework targets the internal state, not just the stimulus.", "response_to_user_option_d": "Incorrect. H = O/D directly addresses the root cause of comparison-driven anxiety — the desire for things beyond what you currently own. Wei''s anxiety was precisely this type, and H = O/D provided the lever to reduce it."}') ON CONFLICT DO NOTHING;
